import ccxt.async_support as ccxt  # noqa: F402

def test_parse_markets():
    exchange = ccxt.Exchange({
        'id': 'sampleex',
    })
    # we don't check empty base or quote inside parseMarkets
    markets = [{
    'id': 'BTC_USD',
    'base': 'BTC',
    'quote': 'USD',
}, {
    'id': None,
    'base': 'ETH',
    'quote': 'USD',
}, {
    'id': 'ETH_USD',
    'base': None,
    'quote': 'USD',
}, {
    'id': 'ETH_USD',
    'base': 'ETH',
    'quote': None,
}]
    parsed_markets = exchange.parse_markets(markets)
    assert len(parsed_markets) == 2, 'Expected 3 parsed markets'
    assert parsed_markets[0] is not None and parsed_markets[0]['base'] == 'BTC', 'Expected BTC as base for the first market'
